# Policy that only allows reading one bucket, nothing more
{
  "Effect": "Allow",
  "Action": ["s3:GetObject", "s3:ListBucket"],
  "Resource": ["arn:aws:s3:::app-logs", "arn:aws:s3:::app-logs/*"]
}

{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Deny",        # Allow or Deny
    "Action": "s3:DeleteBucket",
    "Resource": "*"
  }]
}

