# Terraform: an S3 bucket as the origin behind a distribution
resource "aws_cloudfront_distribution" "site" {
  origin {
    domain_name = aws_s3_bucket.site.bucket_regional_domain_name
    origin_id   = "s3-site"
  }
  default_cache_behavior { target_origin_id = "s3-site" ... }
}

